### 3.2 Code Block 2: Memory-Mapped Shadow Ring-Buffer WAL Executor

```rust
use std::fs::{OpenOptions, File};
use std::os::unix::io::AsRawFd;
use std::sync::atomic::{AtomicU64, Ordering}
```

;
use std::ptr;
use std::sync::atomic::AtomicBool;
use nix::sys::mman::{mmap, munmap, MapFlags, ProtFlags};

const PAGE_SIZE: usize = 4096;
const CACHELINE_BYTES: usize = 64;

/// Align allocation up to the nearest multiple of alignment
#[inline(always)]
const fn align_up(val: usize, align: usize) -> usize {
    (val + align - 1) & !(align - 1)
}

#[repr(C, align(64))]
pub struct WalHeader {
    pub magic: u64,
    pub version: u32,
    pub slot_size: u32,
    pub capacity: u64,
}

#[repr(C, align(64))]
pub struct AtomicCursor {
    pub value: AtomicU64,
    _pad: [u8; CACHELINE_BYTES - std::mem::size_of::<AtomicU64>()],
}

impl AtomicCursor {
    pub const fn new(init: u64) -> Self {
        Self {
            value: AtomicU64::new(init),
            _pad: [0u8; CACHELINE_BYTES - std::mem::size_of::<AtomicU64>()],
        }
    }
}

/// Memory-Mapped Shadow Ring-Buffer WAL Executor.
/// Employs a circular memory-mapped buffer backed by `MAP_SHARED` with an out-of-band 
/// shadow boundary tracker to decouple non-blocking multi-threaded record allocation 
/// from background flush-and-truncate operations.
pub struct ShadowRingWal {
    fd: std::os::unix::io::RawFd,
    mmap_ptr: *mut u8,
    mmap_len: usize,
    capacity: u64,
    mask: u64,
    /// Head cursor: next allocation byte offset (Data-Plane: Hot write-path).
    write_head: AtomicCursor,
    /// Shadow cursor: boundary up to which data is safely persisted via io_uring/fsync.
    persisted_tail: AtomicCursor,
    /// Reclamation cursor: boundary up to which the engine has committed states to L0 SSTs.
    reclaimed_tail: AtomicCursor,
    is_terminating: AtomicBool,
}

unsafe impl Send for ShadowRingWal {}
unsafe impl Sync for ShadowRingWal {}

#[repr(C, packed)]
pub struct WalRecordHeader {
    pub lsn: u64,
    pub len: u32,
    pub crc32: u32,
}

impl ShadowRingWal {
    pub fn new(path: &str, capacity_bytes: usize) -> Result<Self, Box<dyn std::error::Error>> {
        assert!(capacity_bytes > 0 && (capacity_bytes & (capacity_bytes - 1)) == 0, 
            "WAL ring buffer capacity must be a power-of-two.");

        let file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .open(path)?;

        let fd = file.as_raw_fd();
        let total_file_size = align_up(std::mem::size_of::<WalHeader>(), PAGE_SIZE) + capacity_bytes;
        file.set_len(total_file_size as u64)?;

        let mmap_raw = unsafe {
            mmap(
                None,
                std::num::NonZeroUsize::new(total_file_size).unwrap(),
                ProtFlags::PROT_READ | ProtFlags::PROT_WRITE,
                MapFlags::MAP_SHARED | MapFlags::MAP_POPULATE,
                fd,
                0,
            )?
        };

        let mmap_ptr = mmap_raw as *mut u8;

        // Initialize header
        unsafe {
            let hdr = &mut *(mmap_ptr as *mut WalHeader);
            hdr.magic = 0x57414C5348414457; // WALSHADW
            hdr.version = 1;
            hdr.slot_size = PAGE_SIZE as u32;
            hdr.capacity = capacity_bytes as u64;
        }

        Ok(Self {
            fd,
            mmap_ptr,
            mmap_len: total_file_size,
            capacity: capacity_bytes as u64,
            mask: (capacity_bytes as u64) - 1,
            write_head: AtomicCursor::new(0),
            persisted_tail: AtomicCursor::new(0),
            reclaimed_tail: AtomicCursor::new(0),
            is_terminating: AtomicBool::new(false),
        })
    }

    #[inline(always)]
    fn buffer_base(&self) -> *mut u8 {
        unsafe {
            let offset = align_up(std::mem::size_of::<WalHeader>(), PAGE_SIZE);
            self.mmap_ptr.add(offset)
        }
    }

    /// Atomically reserves a contiguous span within the WAL circular ring buffer.
    /// Employs bounded shadow checks to avoid overrunning unpersisted or unreclaimed memory slots.
    pub fn reserve(&self, payload_len: usize) -> Result<(u64, *mut u8), &'static str> {
        let record_size = (std::mem::size_of::<WalRecordHeader>() + payload_len) as u64;
        let aligned_record_size = (record_size + 7) & !7; // 8-byte alignment

        loop {
            let current_head = self.write_head.value.load(Ordering::Acquire);
            let current_reclaimed = self.reclaimed_tail.value.load(Ordering::Acquire);

            // Bounded Shadow Check: Ensure allocation does not overrun unreclaimed data-plane pages
            if (current_head + aligned_record_size).saturating_sub(current_reclaimed) > self.capacity {
                return Err("WAL_RING_BUFFER_PRESSURE_SATURATED");
            }

            // Test-and-set allocation via Fetch-Add on the monotonically increasing global sequence
            let reserved_head = self.write_head.value.fetch_add(aligned_record_size, Ordering::AcqRel);

            // Re-verify bounds race: Ensure no thread interleaved past the shadow ring perimeter
            if (reserved_head + aligned_record_size).saturating_sub(current_reclaimed) > self.capacity {
                return Err("WAL_RING_BUFFER_CAS_OVERRUN_BACKPRESSURE");
            }

            // Compute circular offset
            let ring_offset = (reserved_head & self.mask) as usize;

            // Handle non-contiguous wrapping: if slot straddles circular buffer end, pad and wrap
            if (ring_offset as u64 + aligned_record_size) > self.capacity {
                // Write a zero-length sentinel record to trigger linear re-read wraps on recovery
                unsafe {
                    let target_ptr = self.buffer_base().add(ring_offset);
                    let sentinel = target_ptr as *mut WalRecordHeader;
                    ptr::write_volatile(&mut (*sentinel).len, 0xFFFF_FFFF);
                }
                // Step sequence cursor past the boundary edge to synchronize wrap-around alignment
                let wrap_pad = self.capacity - (ring_offset as u64);
                self.write_head.value.fetch_add(wrap_pad, Ordering::Release);
                continue;
            }

            let write_ptr = unsafe { self.buffer_base().add(ring_offset) };
            return Ok((reserved_head, write_ptr));
        }
    }

    /// Complete write operation and update shadow persistence markers.
    #[inline(always)]
    pub unsafe fn write_commit(
        &self, 
        dest: *mut u8, 
        lsn: u64, 
        data: &[u8], 
        crc: u32
    ) {
        let header = WalRecordHeader {
            lsn,
            len: data.len() as u32,
            crc32: crc,
        };

        // Write record header followed by memory payload
        ptr::copy_nonoverlapping(
            &header as *const _ as *const u8, 
            dest, 
            std::mem::size_of::<WalRecordHeader>()
        );
        ptr::copy_nonoverlapping(
            data.as_ptr(), 
            dest.add(std::mem::size_of::<WalRecordHeader>()), 
            data.len()
        );

        // SFENCE to enforce store visibility to NVMe DMA controllers and parallel io_uring pollers
        std::sync::atomic::fence(Ordering::Release);
    }

    /// Background Control-Plane: Bounded WAL Shadow Flusher
    /// Batches dirty byte pages, invokes non-blocking sync, and advances persisted_tail.
    pub fn advance_shadow_flush(&self, sync_boundary_lsn: u64) -> Result<u64, Box<dyn std::error::Error>> {
        let current_persisted = self.persisted_tail.value.load(Ordering::Acquire);
        let current_head = self.write_head.value.load(Ordering::Acquire);

        if current_persisted >= current_head {
            return Ok(current_persisted);
        }

        let flush_len = (current_head - current_persisted).min(self.capacity);
        let start_offset = (current_persisted & self.mask) as usize;

        let header_pad = align_up(std::mem::size_of::<WalHeader>(), PAGE_SIZE);
        let target_ptr = unsafe { self.mmap_ptr.add(header_pad + start_offset) };

        // Synchronize memory-backed cache lines with underlying non-volatile block architecture
        unsafe {
            libc::msync(
                target_ptr as *mut libc::c_void,
                flush_len as usize,
                libc::MS_ASYNC,
            );
        }

        self.persisted_tail.value.store(current_persisted + flush_len, Ordering::Release);
        Ok(current_persisted + flush_len)
    }

    /// Reclaim stale WAL segments whose mutations have completely transferred to immutable SSTs
    #[inline(always)]
    pub fn reclaim_to_lsn(&self, committed_lsn_offset: u64) {
        self.reclaimed_tail.value.fetch_max(committed_lsn_offset, Ordering::AcqRel);
    }
}

impl Drop for ShadowRingWal {
    fn drop(&mut self) {
        unsafe {
            libc::msync(self.mmap_ptr as *mut libc::c_void, self.mmap_len, libc::MS_SYNC);
            let _ = munmap(
                self.mmap_ptr as *mut libc::c_void, 
                std::num::NonZeroUsize::new(self.mmap_len).unwrap()
            );
            libc::close(self.fd);
        }
    }
}
```

#### Detailed Annotation of Code Block 2:
1. **Cacheline Isolation and False-Sharing Elimination**: `AtomicCursor` explicitly implements `#[repr(C, align(64))]` coupled with explicit byte padding. In high-concurrency storage engines processing $>10^6$ IOPS, concurrent execution of thread-local atomic reservations via `write_head.fetch_add` induces L1D cacheline invalidation storms across CPU cores if `write_head`, `persisted_tail`, and `reclaimed_tail` share a coherence domain. By guaranteeing that each atomic variable occupies its own 64-byte L1 cacheline, we eliminate inter-socket cache line ping-ponging entirely.
2. **Lock-Free Multi-Producer Ticket Allocation**: The `reserve` method avoids coarse-grained mutex locking or reader-writer contention through monotonic sequence reservation (`fetch_add(aligned_record_size, Ordering::AcqRel)`). Concurrent workers atomically slice disjoint memory regions within the memory map concurrently. Memory bounds protection is enforced before and after reservation, ensuring that if backpressure stalls the background drain thread, data-plane threads fail-fast or yield without corrupting memory mapped descriptors.
3. **Circular Straddle Wrapping with Sentinel Escapes**: Circular buffers present structural memory discontinuities when a variable-sized mutation payload spans the physical boundary between `offset = (capacity - 1)` and `offset = 0`. Rather than splitting payloads across two disjoint copy steps—which degrades subsequent zero-copy SIMD deserialization—the implementation inserts a sentinel header (`0xFFFF_FFFF`), pads the cursor to the circular boundary, and re-allocates the contiguous record directly at the zero-offset index.
4. **Decoupled Data-Plane vs. Control-Plane Flusher Dynamics**: Data persistence operates across two distinct phases. Write workers serialize directly into physical pages mapped with `MAP_SHARED | MAP_POPULATE` and issue an explicit atomic release fence (`std::sync::atomic::fence(Ordering::Release)`). A decoupled control-plane worker continuously inspects the distance between `write_head` and `persisted_tail`, issuing asynchronous cache flushes via `libc::msync(..., MS_ASYNC)` or dedicated zero-copy kernel rings (`io_uring` submit-queue polling). This keeps the latency of transaction admission independent of synchronous page-cache writeback overhead.

---

## 4. Production Component Topologies & Concurrency Boundaries

To achieve deterministic sub-millisecond p99.99 write latencies under multi-terabyte state configurations, modern hybrid LSM-B+Tree engines must discard traditional layered storage models. Instead, they organize their execution pipelines around **concurrency domains** and **data-plane vs. control-plane isolation boundaries**.

```
+---------------------------------------------------------------------------------------------------+
|                                  DATA PLANE (Zero-Lock Ingress)                                   |
|                                                                                                   |
|  +------------------+    SIMD Vector Clocks     +-----------------------------------------------+ |
|  | Worker Thread 0  | ------------------------> | AVX2/AVX-512 Partitioned Lock-Free MemTable   | |
|  +------------------+     (Conflict-Free CAS)   | (Non-blocking Skiplist / B-link Cachelines)   | |
|  +------------------+                           +-----------------------------------------------+ |
|  | Worker Thread 1  | ------------------------+                         |                         |
|  +------------------+                         |                         | Freeze Signal           |
|  +------------------+                         v                         v                         |
|  | Worker Thread N  |            +-------------------------+  +---------------------------------+ |
|  +------------------+            | Bounded Shadow WAL Ring |  | Frozen Read-Only MemTable Array | |
|                                  +-------------------------+  +---------------------------------+ |
+-----------------------------------------------|---------------------------------|-----------------+
                                                | Flush Vector                    | Minor Compaction
                                                | (Zero-Copy)                     | (EBR / Epoch Pin)
+-----------------------------------------------v---------------------------------v-----------------+
|                                 CONTROL PLANE (Asynchronous Batching)                             |
|                                                                                                   |
|  +---------------------------------------+       +---------------------------------------------+  |
|  | Bounded Shadow Persister (io_uring)   |       | Autonomous Page Recirculator & Compactor    |  |
|  | Submits NVMe DMA batch syncs          |       | Merges Run Pages, Generates Tiered SSTs     |  |
|  | Updates: persisted_tail               |       | Recycles Obsolete Pages via Lock-Free Pool  |  |
|  +---------------------------------------+       +---------------------------------------------+  |
|                      |                                                  |                         |
|                      v                                                  v                         |
|  +---------------------------------------------------------------------------------------------+  |
|  |                        Non-Volatile NVMe Fabric Storage (L0 -> LN SSTs)                     |  |
|  +---------------------------------------------------------------------------------------------+  |
+---------------------------------------------------------------------------------------------------+
```

### 4.1 Data-Plane Execution Isolation: Lock-Free MemTable and Shared-Nothing Routing

The data plane handles client ingress, SIMD vector clock evaluation, WAL reservation, and active MemTable updates. 

* **Partitioned Sharding without Global Locks**: Client threads are routed to specific partition workers based on uniform key-hashing or explicit partition tokens. Within each partition, operations execute on a lock-free skiplist or a concurrently updated B-link tree. Mutexes are entirely absent from the execution path.
* **Vector-Clock Accelerated Conflict Resolution**: When writes concurrently access intersecting keys across multi-master or distributed edge topologies, the engine executes vector clock resolution using SIMD instructions (e.g., AVX2 or AVX-512), evaluating all clock dimensions simultaneously. This removes conditional branch mispredictions from transaction pipelines.
* **Zero-Allocation Write Paths**: During write reservation, memory payloads map directly into the pre-allocated shadow WAL ring buffer via atomic pointer advancement. No dynamic memory allocations (`malloc`, `madvise`) occur along the hot data path.

### 4.2 Control-Plane Dynamics: Bounded WAL Shadowing and Background Compaction

The control plane runs asynchronously on dedicated, isolated CPU cores (bound via `pthread_setaffinity_np`), isolating the data plane from background operational noise.

* **Bounded WAL Shadow Ring Management**: The control plane polls the WAL ring buffer's delta:
  $$\Delta_{\text{dirty}} = \text{write\_head} - \text{persisted\_tail}$$
  Once $\Delta_{\text{dirty}}$ crosses a predetermined page threshold (e.g., 64 KiB), the persister dispatches an `io_uring` submit-queue entry (SQE) using `IORING_OP_FSYNC` with flags configured to avoid synchronous structural metadata syncs. The background persister advances `persisted_tail` upon reap-cycle completion.
* **MemTable Freezing and Minor Compaction**: When an active MemTable reaches its memory quota, the control plane executes an atomic pointer exchange, swapping the active reference with an empty node and pushing the full instance into an immutable processing list. Ingress threads continue uninterrupted, writing directly to the fresh MemTable.
* **Autonomous Page Recirculation**: The engine avoids returning deallocated leaf and branch nodes to the operating system heap. When SST compactions obsolete data blocks or when an internal index tree reorganizes, pages are routed to an **Epoch-Based Reclamation (EBR)** system. Once all data-plane readers exit the retirement epoch, the memory pages pass into a per-socket lock-free recirculation pool, ready for immediate re-use.

### 4.3 Safe Memory Reclamation via Epoch-Based Synchronization (EBR)

In a high-throughput lock-free storage engine, an active reading thread must be protected against reading memory reclaimed by a background compaction thread. Rather than incurring the significant latency of global reference counting or distributed read-locks, the engine uses a 3-epoch reclamation model:

```
 Global Epoch:  e_global ∈ {0, 1, 2}
 Reader Thread: Announces epoch registration: e_local[thread_id] = e_global

 Compaction / Deletion:
   1. Unlinks Node X from index.
   2. Appends Node X to retirement list: RetireList[e_global].

 Epoch Advance Condition:
   ∀ t ∈ ActiveThreads: (e_local[t] == e_global) ∨ (e_local[t] == INACTIVE)
   ⇒ e_global = (e_global + 1) % 3
   ⇒ Recycle all nodes residing in RetireList[(e_global + 1) % 3] into the Page Pool!
```

Because an unlinked node in epoch $e$ can only be observed by threads that registered in epoch $e$ or earlier, advancing the global epoch across a complete cycle guarantees that no active readers retain references to nodes retired two transitions ago. 

This mechanism allows memory pages to be safely recycled back into the allocation ring without requiring blocking kernel interruptions (`mprotect`, `munmap`) or provoking cross-socket TLB shootdowns.

