## 3. Reference Implementation with Annotated Code Blocks

The following production-grade Rust implementation demonstrates the core lock-free pause barrier and ring-buffer coordination structure. It utilizes atomic operations and Linux futex primitives to halt execution loops deterministically.

```rust
use std::sync::atomic::{AtomicU32, AtomicBool, Ordering};
use std::time::Duration;
use std::io::{Result, Error, ErrorKind};

/// Represents the operational state of an Agent Execution Thread (AET).
#[repr(C)]
pub struct AgentControlBlock {
    /// Bitmask defining pause, abort, and diagnostic flags.
    pub state_flags: AtomicU32,
    /// Futex synchronization word for zero-spin blocking.
    pub futex_word: AtomicU32,
    /// Boolean indicator set when the worker acknowledges the interrupt.
    pub acknowledged: AtomicBool,
}

impl AgentControlBlock {
    pub const FLAG_RUNNING: u32 = 1 << 0;
    pub const FLAG_PAUSED: u32  = 1 << 1;
    pub const FLAG_ABORTED: u32 = 1 << 2;

    pub fn new() -> Self {
        Self {
            state_flags: AtomicU32::new(Self::FLAG_RUNNING),
            futex_word: AtomicU32::new(0),
            acknowledged: AtomicBool::new(false),
        }
    }

    /// Non-cooperative check executed at every tool-dispatch boundary.
    #[inline(always)]
    pub fn assert_execution_validity(&self) -> Result<()> {
        let flags = self.state_flags.load(Ordering::Acquire);

        if (flags & Self::FLAG_ABORTED) != 0 {
            return Err(Error::new(ErrorKind::Interrupted, "Agent execution aborted by control plane"));
        }

        if (flags & Self::FLAG_PAUSED) != 0 {
            self.park_thread();
        }

        Ok(())
    }

    /// Parks the thread via Linux futex syscall without burning CPU cycles.
    #[inline(never)]
    fn park_thread(&self) {
        self.acknowledged.store(true, Ordering::Release);
        let mut current_val = self.futex_word.load(Ordering::Relaxed);

        while (self.state_flags.load(Ordering::Acquire) & Self::FLAG_PAUSED) != 0 {
            // syscall: SYS_futex with FUTEX_WAIT_PRIVATE
            unsafe {
                libc::syscall(
                    libc::SYS_futex,
                    &self.futex_word as *const AtomicU32 as *const u32,
                    libc::FUTEX_WAIT_PRIVATE,
                    current_val,
                    std::ptr::null::<libc::timespec>(),
                    std::ptr::null::<u32>(),
                    0,
                );
            }
            current_val = self.futex_word.load(Ordering::Relaxed);
        }
        self.acknowledged.store(false, Ordering::Release);
    }

    /// Signals the AET to pause execution immediately.
    pub fn request_pause(&self) {
        let mut current = self.state_flags.load(Ordering::Relaxed);
        loop {
            let new_flags = current | Self::FLAG_PAUSED;
            match self.state_flags.compare_exchange_weak(
                current,
                new_flags,
                Ordering::AcqRel,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(actual) => current = actual,
            }
        }
    }

    /// Resumes a paused AET and wakes up the futex waiter.
    pub fn request_resume(&self) {
        let mut current = self.state_flags.load(Ordering::Relaxed);
        loop {
            let new_flags = current & !Self::FLAG_PAUSED;
            match self.state_flags.compare_exchange_weak(
                current,
                new_flags,
                Ordering::AcqRel,
                Ordering::Relaxed,
            ) {
                Ok(_) => {
                    self.futex_word.fetch_add(1, Ordering::Release);
                    unsafe {
                        libc::syscall(
                            libc::SYS_futex,
                            &self.futex_word as *const AtomicU32 as *const u32,
                            libc::FUTEX_WAKE_PRIVATE,
                            1,
                        );
                    }
                    break;
                }
                Err(actual) => current = actual,
            }
        }
    }
}
```

To enforce kernel-level isolation alongside user-space checks, we implement an eBPF tracing hook that intercepts sensitive system calls (e.g., `sys_socket`, `sys_write`, `sys_execve`) when an agent thread enters a tainted state.

```c
#include <linux/bpf.h>
#include <linux/ptrace.h>
#include <bpf/bpf_helpers.h>

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u32);   // PID
    __type(value, __u32); // State flags
} agent_states SEC(".maps");

SEC("tracepoint/syscalls/sys_enter_write")

int monitor_agent_writes(struct trace_entry *ctx) {
    __u32 pid = (__u32)(bpf_get_current_pid_tgid() >> 32);
    __u32 *flags = bpf_map_lookup_elem(&agent_states, &pid);

    if (flags) {
        // If ABORT flag is set (bit 2), block the syscall by returning -EPERM
        if ((*flags) & 4) {
            bpf_override_return(ctx, -1); // -EPERM equivalent in override context
        }
    }
    return 0;
}

